  function maybeAwardCertificate(){if(!certificateReady()||state.awards.certificateIssued)return false;const next=JSON.parse(JSON.stringify(state));next.awards.certificateIssued=Date.now();next.profile.badge='eco-master';K.event(next,'game','eco-certificate',next.awards.certificateIssued);if(!K.write(stateStorage,next)){toast('证书条件已满足，但保存失败；请检查浏览器存储空间后重试。');return false}state=next;renderHall();return true;}
