    state.tutorialSeen=true;persist();
    const tip=document.createElement('div');tip.className='new-user-guide';tip.innerHTML='<div><h2>欢迎来到垃圾分类小达人</h2><p>先在环保知识探索馆学习分类知识，再挑战四种小游戏。完成游戏可以获得积分并兑换环保奖励。</p><button>开始探索</button></div>';
