  function modalHeader(titleKey,subtitleKey,eyebrowKey){const symbols={game:'star',classroom:'book',account:'user',settings:'settings',history:'history',admin:'lock',reset:'history',shop:'shop',redeem:'coin',quiz:'book',guide:'book','shop-admin':'lock',certificate:'star'};return `<button class="close-button" data-action="close" aria-label="${escape(t('common.close'))}">${icon('close')}</button><header class="modal-header"><span class="modal-symbol" aria-hidden="true">${icon(symbols[modalState?.type]||'leaf')}</span><div>${eyebrowKey?`<p class="modal-eyebrow">${E(eyebrowKey)}</p>`:''}<h2 id="modal-title">${E(titleKey)}</h2>${subtitleKey?`<p class="modal-subtitle">${E(subtitleKey)}</p>`:''}</div></header>`;}
  function openDialog(type,extra={}){if(!modal.open)previousFocus=document.activeElement;modalState={type,...extra};syncMusicTrack();renderDialog();if(!modal.open)modal.showModal();setTimeout(()=>modal.querySelector('input[autofocus]')?.focus(),30)}
  function closeDialog(){stopQuizTimer();stopQuizAuto();FX.clearCelebration();modal.close();document.body.appendChild($('toast'));modalState=null;syncMusicTrack();if(previousFocus?.isConnected)previousFocus.focus();else document.querySelector('.top-nav button')?.focus()}
  function gameDialog(){const g=C.games.find(x=>x.id===modalState.game),key='game.'+g.id+'.',done=!!state.completed[g.id],p=K.progress(state);const feedback=done?`<div class="completion-feedback" role="status"><span>${icon('check')}</span><div><strong>${E(p.percent===100?'intro.successAll':'intro.successTitle')}</strong><p>${E('intro.successBody')}</p></div><span class="result-percent">${p.percent}%</span></div>`:`<p class="preview-note">${E('intro.note')}</p>`;return `${modalHeader(key+'title',null,'common.previewLabel')}<div class="intro-overview ${g.color}"><div><span class="intro-tag">${E('intro.goal')}</span><p>${E(key+'goal')}</p></div>${art(g)}</div><h3 class="steps-title">${E('intro.how')}</h3><ol class="steps">${g.steps.map((_,i)=>`<li><span class="step-number">0${i+1}</span>${E(key+'step'+i)}</li>`).join('')}</ol>${feedback}<p class="game-points-note">${icon('coin')}${E(done?'points.claimed':'points.gameRule',{points:C.economy.gameReward})}${modalState.gain?`<strong>${E('points.gained',{points:modalState.gain})}</strong>`:''}</p><div class="modal-actions"><button class="primary-button" data-action="play" data-game="${g.id}">${icon('star')}${E('play.start')}</button><button class="secondary-button" data-action="classroom">${icon('book')}${E('intro.lesson')}</button><button class="secondary-button" data-action="shop">${icon('shop')}${E('nav.shop')}</button></div>`;}
  const lessonChecks={
    types:{question:'湿垃圾进入厌氧消化环节后，哪种情况最符合实际？',options:[['oxygen','持续通入大量氧气，让有机物快速燃烧'],['anaerobic','在缺氧环境中由微生物分解有机物，产生沼气'],['dry','先把垃圾完全晒干，再直接变成电能']],answer:'anaerobic',hint:'留意“厌氧”这个词：它强调的是有氧还是缺氧？',why:'关键是厌氧消化：微生物在缺氧环境中分解有机物，产生以甲烷和二氧化碳为主要成分的沼气。沼气可用于能源利用，处理后的残余物还需按规范继续处理。'},
    prepare:{question:'回收塑料瓶里混入饮料残液和其他材质，最可能带来什么影响？',options:[['bury','完全不影响，所有材料都能直接一起再生'],['wash','增加分拣与清洁难度，部分情况下还会影响再生品质'],['burn','只会让塑料瓶颜色变深，不影响后续加工']],answer:'wash',hint:'想一想：再生加工前，材料是否需要被识别、分开并达到相应清洁要求？',why:'回收物通常还要经过分拣、清洗、破碎等工序，再根据材质和工艺加工成再生原料。混入食物残渣或其他材质会增加分选与清洁难度，并可能影响再生品质。'},
    daily:{question:'买午餐时，哪种做法最符合“源头减量”的思路？',options:[['sort','照常购买，吃不完后再把剩菜分好类'],['reduce','按食量购买，减少不必要包装，并在条件允许时重复使用餐具'],['recycle','优先选择包装更多但标有可回收标志的商品']],answer:'reduce',hint:'源头减量发生在垃圾产生之前；分类和回收通常发生在物品成为废弃物之后。',why:'源头减量意味着尽量不产生不必要的垃圾。按需购买、使用可重复用品和减少一次性包装，通常比垃圾产生后再处理更优先；剩下的垃圾再做好分类。'}
  };
  const exploreDetails={
    types:{icon:'leaf',kicker:'湿垃圾资源化',intro:'一份剩饭并不一定是旅程的终点。经过规范收运和预处理后，适合的有机物可以进入厌氧消化等处理环节。',steps:[['01','收集与预处理','去除不适合进入处理流程的杂物，并进行必要的破碎、制浆等预处理。','预处理不是把所有东西都变成资源，而是尽量让后续设备接收适合处理的有机物。'],['02','厌氧消化','在缺氧环境中，微生物分解有机物，产生沼气。','可以把它想成一个密闭的“微生物工作间”：条件合适时，微生物把有机物转化成沼气和消化残余物。'],['03','能源与残余物利用','沼气可用于发电或供热；经适当净化后也可用于其他能源场景。沼渣、沼液需按规范处理和利用。','资源化并不代表零残留。沼渣、沼液是否能利用，要看处理工艺、质量要求和规范，不能直接假定都能当肥料。']],fact:'重点不是“垃圾凭空消失”，而是把合适的有机物转化为可利用资源，同时妥善处理剩余物。'},
    prepare:{icon:'recycle',kicker:'可回收物再生',intro:'投进回收桶只是回收链条的开始。不同材料要经过分拣与处理，才能成为符合要求的再生原料。',steps:[['01','分拣识别','按材料、颜色或其他要求分开，避免不同材质混杂。','同样是包装，瓶身、瓶盖、标签可能采用不同材料；具体工厂会按回收标准处理，不能只凭外观判断所有部件都相同。'],['02','清洁与加工','根据材料和污染情况进行清洗、破碎或压缩等处理。','残液和食物残渣会增加清洗负担；不同材料所需工序不同，并不是所有回收物都走同一条流水线。'],['03','再生利用','加工成再生颗粒、纸浆或其他原料，再进入后续生产。','再生原料还要符合后续产品的质量要求；“可回收”不等于每件物品都必然被成功回收。']],fact:'干净、相对单一的回收材料通常更容易处理。把剩菜、液体和外包装混在一起，会增加分拣与清洁成本。'},
    daily:{icon:'sparkles',kicker:'从源头减量',intro:'垃圾管理不只发生在垃圾桶旁。购买之前的选择，也会影响最后产生多少废弃物。',steps:[['01','减少不必要的消耗','按需购买食物，避免买多后变成厨余；优先选择耐用、少包装的产品。','例如先看自己能吃多少，再决定购买份量；少买用不上的东西，才能从源头减少后续处理量。'],['02','重复使用','自带水杯、餐具或购物袋，在卫生和使用条件允许时延长物品寿命。','重复使用也要考虑清洁、耐用和实际需要；不是为了环保而囤积更多物品。'],['03','分类并妥善处理','无法避免的废弃物再按规定分类投放，让后续回收与处理更有效。','减量优先不等于可以跳过分类。确实产生的废弃物，仍然需要按当地规定正确投放。']],fact:'环保行动可以按“源头减量—重复使用—分类回收—妥善处理”逐层思考，而不是只在最后一步努力。'}
  };
  function exploreReward(key,amount,source){state.wallet.learning=state.wallet.learning||{};if(state.wallet.learning[key])return 0;const time=Date.now();state.wallet.learning[key]={amount,time};K.event(state,'points','explore-'+key,time,{amount,source:'exploration'});return amount;}
  function lessonDialog(){const id=modalState.lesson||'types',key='lesson.'+id+'.',check=lessonChecks[id],detail=exploreDetails[id];const answer=modalState.lessonCheckAnswer,correct=answer===check.answer,questionReward=state.wallet.learning['explore-question-'+id],completionReward=state.wallet.learning['explore-complete-'+id],done=state.lessons.includes(id);const body=`<section class="explore-intro"><span class="explore-kicker">${detail.kicker}</span><p>${detail.intro}</p></section><section class="explore-journey" aria-label="探索流程">${detail.steps.map(([num,title,text,more])=>`<article class="explore-step"><span class="explore-step-number">${num}</span><div><h4>${title}</h4><p>${text}</p><details class="explore-more"><summary>展开看一个细节</summary><p>${more}</p></details></div></article>`).join('')}</section><aside class="explore-fact"><strong>发现一个关键点</strong><p>${detail.fact}</p></aside>`;
    const checkUI=`<section class="guided-check explore-challenge" aria-labelledby="guided-check-title"><div class="guided-step">知识挑战 · 答对得分</div><h3 id="guided-check-title">${check.question}</h3><p>这不是垃圾分类操作题，而是检验你是否理解了刚才的处理原理。</p><div class="guided-options">${check.options.map(([value,label])=>`<button type="button" class="guided-option ${answer===value?(correct?'is-correct':'is-wrong'):''}" data-action="lesson-check" data-answer="${value}" data-lesson="${id}" aria-pressed="${answer===value}" ${correct?'disabled':''}>${label}${answer===value?(correct?' ✓':' ↻'):''}</button>`).join('')}</div>${answer!==undefined?`<div class="guided-feedback ${correct?'success':'retry'}" role="status"><strong>${correct?'理解正确！': '再想一想。'}</strong><p>${correct?check.why:(check.hint||'回到上面的流程，找一找哪个步骤最能解释这个问题。你可以重新选择。')}</p>${correct?`<span class="explore-reward">${modalState.lessonCheckPoints>0?'本次获得 +5 探索积分':'本题积分已领取'}</span>`:''}</div>`:''}</section>`;
    return `${modalHeader('lesson.title','lesson.subtitle')}<div class="explore-overview"><span class="explore-overview-icon">✦</span><div><strong>自由探索 · 任务解锁奖励</strong><p>三个展区都可以随时进入，不必按顺序。读完展区并答对挑战，即可记录学习进度。</p></div><span class="explore-total">${state.lessons.length}/3</span></div><div class="lesson-tabs" role="tablist" aria-label="探索展区">${C.lessons.map((l,i)=>`<button class="lesson-tab ${l.id===id?'active':''}" role="tab" aria-selected="${l.id===id}" data-action="lesson" data-lesson="${l.id}"><span>0${i+1}</span>${E('lesson.'+l.id+'.title')}${state.lessons.includes(l.id)?icon('check'):''}</button>`).join('')}</div><p class="eyebrow">${E(key+'eyebrow')}</p><h3 class="lesson-section-heading">${E(key+'title')}</h3><p class="lesson-description">${E(key+'description')}</p>${body}${checkUI}<details class="lesson-source-details"><summary>需要核对分类细节时，再查看上海市分类指南原图（2019版）</summary><p>分类指南用于查证具体投放规则；本展区重点帮助你理解垃圾处理、资源循环与源头减量。</p><button class="secondary-button" data-action="guide">${icon('book')}查看分类指南原图</button></details><div class="lesson-bottom"><p>${done?'本展区已完成，内容仍可随时重看。':correct?'答题已通过，可以领取展区完成奖励。':'先探索内容，再完成知识挑战。答对后即可记录本展区。'}</p><button class="primary-button" data-action="learn" data-lesson="${id}" ${done||!correct?'disabled':''}>${icon(done?'check':'star')}${done?'展区已完成':'完成探索 · +10 分'}</button></div><div class="lesson-quiz-cta"><div><h3>${E('quiz.title')}</h3><p>想继续挑战分类规则？主游戏和知识测验可以练习实际应用。</p></div><button class="primary-button" data-action="quiz">${E('quiz.start')}${icon('arrow')}</button></div>`;
  }
  const QUIZ_SECONDS=15;
  function stopQuizTimer(){if(quizTimer!==null){clearInterval(quizTimer);quizTimer=null}}
  function makeQuiz(mode='practice'){const bank=window.EcoQuizBank||[];let questions;if(mode==='review'){const pending=new Set(Object.entries(state.review?.items||{}).filter(([,r])=>r?.wrongCount>0&&!r.mastered).map(([id])=>id));questions=G.shuffle(bank.filter(q=>pending.has(q.id)))}else questions=G.shuffle([...bank]).slice(0,10);return {mode,account:activeAccount,questions,index:0,correct:0,selected:null,saved:false,timeLeft:QUIZ_SECONDS,timeouts:0,points:0,autoNext:5}}
  function applyQuizPoints(quiz,delta){if(quiz.mode==='formal'){const correct=delta>0?Number(adminPoints.quiz.correct):Number(adminPoints.quiz.wrong);quiz.points+=Number.isFinite(correct)?correct:delta}}
  function answerLearningQuestion(quiz,item,correct){const result=K.recordLearningAnswer(state,item,correct);if(result.points){quiz.learningPoints=(quiz.learningPoints||0)+result.points}persist();renderHall();return result}
  function startQuizAutoAdvance(quiz){stopQuizAuto();quiz.autoNext=5;const update=()=>{const node=modal.querySelector('[data-auto-next]');if(node)node.textContent=String(quiz.autoNext)};update();quizAutoTick=setInterval(()=>{if(modalState?.type!=='quiz'||modalState.quiz!==quiz||quiz.selected===null){stopQuizAuto();return}quiz.autoNext=Math.max(0,quiz.autoNext-1);update()},1000);quizAutoTimer=setTimeout(()=>{stopQuizAuto();if(modalState?.type==='quiz'&&modalState.quiz===quiz&&quiz.selected!==null)advanceQuiz()},5000)}
  function startQuizTimer(){stopQuizTimer();const quiz=modalState?.type==='quiz'?modalState.quiz:null;if(!quiz||quiz.selected!==null||!quiz.questions[quiz.index])return;quiz.timeLeft=Number.isFinite(quiz.timeLeft)?quiz.timeLeft:QUIZ_SECONDS;const update=()=>{const value=modal.querySelector('[data-quiz-time]'),fill=modal.querySelector('.quiz-timer-fill'),row=modal.querySelector('.quiz-timer-row');if(value)value.textContent=String(quiz.timeLeft);if(fill)fill.style.width=(quiz.timeLeft/QUIZ_SECONDS*100)+'%';if(row)row.classList.toggle('is-urgent',quiz.timeLeft<=3)};update();quizTimer=setInterval(()=>{if(modalState?.type!=='quiz'||modalState.quiz!==quiz||quiz.selected!==null){stopQuizTimer();return}quiz.timeLeft=Math.max(0,quiz.timeLeft-1);update();if(quiz.timeLeft<=3&&quiz.timeLeft>0)sfx('urgent');if(quiz.timeLeft===0){stopQuizTimer();quiz.selected='__timeout__';quiz.timeouts++;applyQuizPoints(quiz,-5);answerLearningQuestion(quiz,quiz.questions[quiz.index],false);sfx('wrong');renderDialog()}},1000)}
  function advanceQuiz(){const quiz=modalState?.quiz;if(!quiz||modalState.type!=='quiz'||quiz.selected===null)return;stopQuizTimer();stopQuizAuto();quiz.index++;quiz.selected=null;quiz.timeLeft=QUIZ_SECONDS;if(quiz.index===quiz.questions.length&&!quiz.saved){if(quiz.mode!=='review')K.recordQuiz(state,quiz.correct);quiz.saved=true;persist();renderHall()}renderDialog();if(quiz.index===quiz.questions.length&&quiz.correct>=Math.ceil(quiz.questions.length*.8))FX.celebrate({kind:'lesson',anchor:modal.querySelector('.quiz-result')})}
  function quizModeDialog(){const account=currentAccount(),used=!!account?.formalQuizUsed,review=K.reviewStats(state);return `${modalHeader('quiz.title','quiz.subtitle')}<div class="quiz-mode-cards"><article class="quiz-mode-card"><span class="quiz-mode-kicker">不限次数</span><h3>练习模式</h3><p>随机抽取10题。答题后会显示正确答案与解析；每道题首次答对获得${adminPoints.knowledge}知识积分，不重复发放。</p><button class="primary-button" data-action="quiz-mode-practice">开始练习 ${icon('arrow')}</button></article><article class="quiz-mode-card"><span class="quiz-mode-kicker">错题清零</span><h3>错题再练</h3><p>待消灭错题 ${review.pending} 道 · 已掌握 ${review.mastered} 道。答对后从错题库移除；每道题的${adminPoints.knowledge}积分只发一次。</p><button class="primary-button" data-action="quiz-mode-review" ${review.pending?'':'disabled'}>${review.pending?'开始消灭错题':'当前没有待复习错题'} ${icon(review.pending?'arrow':'check')}</button><p class="quiz-account-note">已获得知识积分：${review.learningPoints} 分。完成整套题库后，每人获得相同的题库积分。</p></article><article class="quiz-mode-card"><span class="quiz-mode-kicker">正式挑战</span><h3>答题模式</h3><p>每个账号仅能参加一次正式答题。答对 +${adminPoints.quiz.correct} 分，答错或超时 ${adminPoints.quiz.wrong} 分；这是挑战成绩，与题库掌握积分分开记录。</p>${account?`<p class="quiz-account-note">当前账号：${escape(activeAccount)} · ${used?'已参加正式答题':'尚未参加'}</p><button class="primary-button" data-action="quiz-mode-formal" ${used?'disabled':''}>${used?'正式答题已完成':'开始正式答题'} ${icon(used?'check':'arrow')}</button>`:`<p class="quiz-account-note">请先在“我的账户”注册或登录，才能参加正式答题。</p><button class="primary-button" data-action="quiz-login">前往登录 ${icon('arrow')}</button>`}</article></div><div class="modal-actions"><button class="secondary-button" data-action="close">稍后再说</button></div>`}
  function quizDialog(){const quiz=modalState.quiz,item=quiz.questions[quiz.index];if(!item){stopQuizTimer();stopQuizAuto();if(!quiz.saved){if(quiz.mode!=='review')K.recordQuiz(state,quiz.correct);if(quiz.mode==='formal'){const accounts=readAccounts(),account=accounts[quiz.account];if(account&&!account.formalQuizUsed){account.quizPoints=(Number(account.quizPoints)||0)+quiz.points;account.formalQuizUsed=true;account.formalQuizCompletedAt=Date.now();delete account.formalQuizStarted;if(!writeAccounts(accounts))toast('toast.storage')}}quiz.saved=true;persist();renderHall()}const account=readAccounts()[quiz.account];return `${modalHeader('quiz.title','quiz.subtitle')}<div class="quiz-result"><span class="quiz-result-kicker">${quiz.mode==='formal'?'正式答题完成':quiz.mode==='review'?'错题复习完成':'练习完成'}</span><strong>${quiz.mode==='formal'?quiz.points:quiz.mode==='review'?(quiz.learningPoints||0):quiz.correct}<small> ${quiz.mode==='formal'?'挑战积分':quiz.mode==='review'?'本次掌握积分':' / '+quiz.questions.length+' 题'}</small></strong><h3>${quiz.mode==='review'?(K.reviewStats(state).pending===0?'太棒了，错题已清零！':'本轮完成，继续加油！'):quiz.correct>=Math.ceil(quiz.questions.length*.8)?'掌握得不错！':'再练几次会更熟练'}</h3><p>答对 ${quiz.correct} / ${quiz.questions.length} 题 · 超时 ${quiz.timeouts} 题</p>${quiz.mode==='formal'?`<p>本次挑战积分：${quiz.points>=0?'+':''}${quiz.points} 分；账号累计答题积分：${Number(account?.quizPoints)||0} 分。</p><p class="quiz-account-note">正式答题每个账号仅限一次，已记录完成状态。</p>`:quiz.mode==='review'?`<p>待复习错题还剩 ${K.reviewStats(state).pending} 道。知识积分按每道题固定10分发放，同一道题不会重复领奖。</p>`:`<p>每道题首次答对可获得固定10分知识积分；答错题会进入错题再练。</p>`}<div class="modal-actions">${quiz.mode!=='formal'&&quiz.mode!=='review'?'<button class="primary-button" data-action="quiz-retry">再练一次</button>':''}${quiz.mode==='review'&&K.reviewStats(state).pending?'<button class="primary-button" data-action="quiz-mode-review">继续消灭错题</button>':''}<button class="secondary-button" data-action="quiz">查看错题与练习</button><button class="secondary-button" data-action="classroom">返回环保小课堂</button><button class="secondary-button" data-action="close">返回大厅</button></div></div>`;}
    const selected=quiz.selected!==null,timedOut=quiz.selected==='__timeout__';
    return `${modalHeader('quiz.title','quiz.subtitle')}<div class="quiz-progress"><span>第 ${quiz.index+1} / ${quiz.questions.length} 题</span><span>已答对 ${quiz.correct} 题${quiz.mode==='formal'?` · 挑战积分 ${quiz.points>=0?'+':''}${quiz.points}`:quiz.mode==='review'?` · 本次知识积分 +${quiz.learningPoints||0}`:''}</span></div><div class="quiz-track"><div style="width:${quiz.questions.length?quiz.index/quiz.questions.length*100:0}%"></div></div><div class="quiz-timer-row"><span>${selected?(timedOut?'时间到，已显示正确答案':'已显示正确答案与解析'):'请在15秒内选择答案'}</span><strong><span data-quiz-time>${selected?'—':quiz.timeLeft}</span>${selected?'':' 秒'}</strong></div><div class="quiz-timer-track"><div class="quiz-timer-fill ${quiz.timeLeft<=3?'is-urgent':''}" style="width:${selected?0:quiz.timeLeft/QUIZ_SECONDS*100}%"></div></div><div class="quiz-item"><span class="quiz-question-mark" aria-hidden="true">环保知识</span><h3>${escape(item.question)}</h3><p>${escape(item.topic||'上海生活垃圾分类')}</p></div><div class="quiz-answers">${item.options.map((label,i)=>`<button class="secondary-button ${selected&&i===item.answer?'is-right':quiz.selected===i?'is-wrong':''}" data-action="quiz-answer" data-choice="${i}" ${selected?'disabled':''}><span class="quiz-option-letter">${String.fromCharCode(65+i)}</span><span>${escape(label)}</span></button>`).join('')}</div>${selected?`<div class="quiz-explanation ${quiz.selected===item.answer?'quiz-explanation-correct':''}"><strong>${timedOut?'时间到！正确答案是：'+escape(item.options[item.answer]):quiz.selected===item.answer?'回答正确！':'正确答案：'+escape(item.options[item.answer])}</strong><p>${escape(item.why)}</p><p class="quiz-auto-note">${quiz.mode==='review'&&quiz.selected!==item.answer?'这道错题仍保留在复习清单中。':quiz.selected===item.answer?'这道题已记录为掌握。':''} ${quiz.autoNext>0?'将在 <strong data-auto-next>'+quiz.autoNext+'</strong> 秒后自动进入下一题':'正在进入下一题…'} · 也可以现在点击继续</p></div><div class="modal-actions"><button class="primary-button" data-action="quiz-next">${E(quiz.index===quiz.questions.length-1?'quiz.results':'quiz.next')}${icon('arrow')}</button></div>`:''}`;}
  function settleGame(id,outcome,runId){const before=K.progress(state).percent;if(exhibitionMode){recordLeaderboard(id,{name:state.profile.name||'游客',score:outcome?.score||0,time:outcome?.elapsed||0,finishedAt:Date.now()})}if(outcome?.practice){if(!exhibitionMode&&Array.isArray(outcome.wrongItems)&&outcome.wrongItems.length){K.recordGameWrong(state,id,outcome.wrongItems,'practice');persist()}renderHall(before);return {practice:true,credit:0,bonus:0,coins:0,progress:K.progress(state),wallet:K.wallet(state)}}if(!exhibitionMode&&Array.isArray(outcome?.wrongItems)&&outcome.wrongItems.length){K.recordGameWrong(state,id,outcome.wrongItems,'formal')}if(id==='ludo'&&outcome.multi&&Array.isArray(outcome.rankings)){let ledger;try{ledger=JSON.parse(storage.getItem(LUDO_LEDGER_KEY)||'{"players":{},"runs":{}}')}catch{ledger={players:{},runs:{}}}ledger.players=ledger.players||{};ledger.runs=ledger.runs||{};if(!ledger.runs[runId]){for(const p of outcome.rankings){const name=String(p.name||'玩家').trim().slice(0,16)||'玩家';const points=window.EcoGameEngine.rankPoints(p.rank);ledger.players[name]=Math.max(0,Number(ledger.players[name])||0)+points;p.gained=points;p.total=ledger.players[name]}ledger.runs[runId]=Date.now();const runKeys=Object.keys(ledger.runs);if(runKeys.length>500)for(const key of runKeys.sort((a,b)=>ledger.runs[a]-ledger.runs[b]).slice(0,runKeys.length-500))delete ledger.runs[key];try{storage.setItem(LUDO_LEDGER_KEY,JSON.stringify(ledger))}catch{toast('飞行棋个人积分保存失败；本局名次积分仍显示在结算页。')}}else for(const p of outcome.rankings){p.gained=window.EcoGameEngine.rankPoints(p.rank);p.total=Number(ledger.players[p.name])||0}return {credit:0,bonus:0,coins:0,personalRankPoints:true,progress:K.progress(state),wallet:K.wallet(state)}}const result=K.recordRun(state,id,runId,outcome);persist();renderHall(before);document.dispatchEvent(new CustomEvent('hub:progress',{detail:{...result.progress,gameId:id,source:'game',pointsGained:result.credit,balance:result.wallet.balance}}));if(maybeAwardCertificate())showCertificate();return result}
  function exitPlay(){const id=activeGame?.getSnapshot().gameId;activeGame?.destroy();activeGame=null;$('game-screen').hidden=true;$('app').inert=false;$('editor').inert=false;document.body.classList.remove('game-open');syncMusicTrack();renderHall();renderEditor();document.querySelector(`.game-card[data-game="${id}"]`)?.focus()}
  function setExhibitionMode(enabled){if(enabled){const pwd=window.prompt('请输入管理员密码开启大屏模式');if(!pwd){toast('已取消：未输入管理员密码，展会模式未开启');return false}let saved='';try{saved=localStorage.getItem('eco_admin_password')||''}catch{} if(saved&&pwd!==saved){toast('管理员密码错误');return false;} if(!saved){try{localStorage.setItem('eco_admin_password',pwd)}catch{}}}if(activeGame)exitPlay();if(!persist())return false;exhibitionMode=!!enabled;try{if(exhibitionMode)window.localStorage.setItem(EXHIBITION_KEY,'1');else window.localStorage.removeItem(EXHIBITION_KEY)}catch{}if(exhibitionMode){saveAccountSession('');state=K.defaults();loadSoundPrefs();K.write(stateStorage,state);toast('展会轮换模式已开启：每位游客结束后点击“下一位游客”，个人记录将清空。')}else{saveAccountSession('');state=K.read(stateStorage);loadSoundPrefs();toast('已退出展会轮换模式。')}renderHall();renderEditor();return true}
  function nextVisitor(){if(!exhibitionMode)return false;if(activeGame)exitPlay();saveAccountSession('');state=K.defaults();loadSoundPrefs();const ok=K.write(stateStorage,state);renderHall();renderEditor();if(!ok)toast('清理本轮记录失败，请检查浏览器存储权限。');else toast('已清理上一位游客的本轮记录，可以开始下一位。');return ok}
  function readLeaderboard(){try{const v=JSON.parse(storage.getItem(LEADERBOARD_KEY)||'{}');return v&&typeof v==='object'?v:{}}catch{return {}}}
  function writeLeaderboard(map){try{storage.setItem(LEADERBOARD_KEY,JSON.stringify(map));return true}catch{return false}}
  function recordLeaderboard(gameId,entry){const score=Math.max(0,Math.round(Number(entry.score)||0));if(score<=0)return;const map=readLeaderboard(),list=map[gameId]||[];list.push({name:String(entry.name||'游客').trim().slice(0,16)||'游客',score,time:Math.max(0,Math.round(Number(entry.time)||0)),finishedAt:Number(entry.finishedAt)||Date.now()});map[gameId]=list.slice(-200);writeLeaderboard(map);}
  function sortedLeaderboard(list){return [...(list||[])].sort((a,b)=>b.score-a.score||a.time-b.time||a.finishedAt-b.finishedAt).slice(0,50);}
  function gameReviewDialog(){const games=['sorter','runner','ludo'];const sections=games.map(gid=>{const game=C.games.find(x=>x.id===gid);if(!game)return '';const list=(K.gameWrongList(state)[gid]||[]).slice().reverse();if(!list.length)return '';const pending=list.filter(x=>!x.restored).length;const items=list.map(w=>{const item=D.byId[w.item];if(!item)return '';const wrong=w.chosen?(w.chosen==='missed'?`<span class="gr-wrong">没有接到 · 错过了它</span>`:`<span class="gr-wrong">你的答案：${escape(t('category.'+w.chosen+'.name'))}</span>`):'';const done=w.restored?`<span class="gr-done">${icon('check')}已消灭${w.source==='formal'?' · 积分已恢复':' · 练一练错题不恢复积分'}</span>`:'';const cats=w.restored?'':`<div class="gr-cats">${D.categories.map(c=>`<button class="gr-cat" data-action="review-cat" data-game="${gid}" data-item="${w.item}" data-cat="${c.id}" style="--cat:${c.color}">${escape(t('category.'+c.id+'.name'))}</button>`).join('')}</div>`;return `<div class="gr-item ${w.restored?'gr-cleared':''}"><div class="gr-item-head"><img src="${item.image}" alt="" loading="lazy"><strong>${escape(t('trash.'+w.item+'.name'))}</strong><span class="gr-expected">正确类别：${escape(t('category.'+w.expected+'.name'))}</span>${wrong}${done}</div><p class="gr-why">${escape(t('trash.'+w.item+'.why'))}</p>${cats}<div class="gr-fb" data-fb="${w.item}"></div></div>`}).join('');return `<section class="gr-section"><h3>${escape(game.name)} · 待消灭 ${pending}/${list.length}</h3><div class="gr-list">${items}</div></section>`}).join('');return `${modalHeader('错题本','游戏答错的垃圾自动收进这里：答对分类即可消灭并恢复积分（与游戏内答对分值一致）；练一练产生的错题可消灭但不恢复积分。')}<div class="gr-wrap">${sections||`<div class="empty-state">${icon('leaf')}<p>还没有游戏错题。玩一局分类游戏，答错的物品会自动收进这里。</p></div>`}</div><div class="modal-actions"><button class="primary-button" data-action="close">${E('common.close')}</button></div>`}
  function leaderboardDialog(){const g=C.games.find(x=>x.id===modalState.game),list=sortedLeaderboard(readLeaderboard()[modalState.game]||[]);const best=list[0]||null;return `${modalHeader('排行榜','展会大屏 · 姓名 / 得分 / 用时，分数高优先，用时少优先')}<div class="leaderboard-wrap"><div class="leaderboard-podium">${best?`<div class="lb-top"><span>🏆</span><strong>${escape(best.name)}</strong><b>${best.score}<small>分</small></b><em>用时 ${best.time} 秒</em></div>`:`<div class="lb-top lb-empty"><span>⭐</span><strong>等待第一位挑战者</strong><b>—</b><em>先完成一局，成绩会出现在这里</em></div>`}</div>${list.length?`<ol class="leaderboard-list">${list.map((row,i)=>`<li class="${i===0?'lb-first':''}"><span class="lb-rank">${i+1}</span><strong>${escape(row.name)}</strong><span class="lb-score">${row.score}<small>分</small></span><span class="lb-time">${row.time}<small>秒</small></span><time>${escape(timeLabel(row.finishedAt))}</time></li>`).join('')}</ol>`:`<p class="empty-state">${icon('leaf')}<p>还没有成绩记录，快去挑战一局吧！</p></p>`}<div class="modal-actions"><button class="primary-button" data-action="play" data-game="${g?g.id:''}">${icon('star')}再玩一次</button><button class="secondary-button" data-action="close">${E('common.close')}</button></div></div>`;}
  function exhibitionNameDialog(){const g=C.games.find(x=>x.id===modalState.game);return `${modalHeader('game.'+(g?g.id:'match')+'.title',null)}<form id="exhibition-name-form" class="exhibition-name-form"><span class="exhibition-name-icon">✍️</span><h3>挑战者姓名</h3><p>输入姓名后开始挑战，结束即可进入排行榜。</p><div class="form-field"><input id="exhibition-name" name="visitor" type="text" maxlength="16" placeholder="请输入您的姓名" required autofocus></div><button type="button" class="secondary-button random-nick-button" data-action="random-nick">🎲 随机昵称</button><div class="modal-actions"><button class="primary-button" type="submit">开始挑战 ${icon('arrow')}</button><button class="secondary-button" type="button" data-action="close">${E('common.cancel')}</button></div></form>`;}
  function startPlay(id){if(!C.games.some(g=>g.id===id))return false;if(exhibitionMode){openDialog('exhibition-name',{game:id});return true}launchGame(id);return true}
  function launchGame(id){if(activeGame)exitPlay();if(modal.open)closeDialog();$('app').inert=true;$('editor').inert=true;$('editor').hidden=true;document.body.classList.add('game-open');$('game-screen').hidden=false;activeGame=window.EcoGames.mount({host:$('game-screen'),gameId:id,getState:()=>state,getText:t,onFinish:(outcome,runId)=>settleGame(id,outcome,runId),onExit:exitPlay,onVisitorNext:nextVisitor,onLeaderboard:()=>openDialog('leaderboard',{game:id}),onReview:()=>openDialog('game-review'),exhibitionMode,sfx,celebrate:anchor=>FX.celebrate({percent:K.progress(state).percent,anchor})});syncMusicTrack();return true}
  function accountDialog(){const p=K.progress(state),w=K.wallet(state),profile=modalState.profileDraft||state.profile,account=currentAccount();return `${modalHeader('account.title','账号注册与登录保存在当前浏览器。换浏览器或设备不会同步。')}${modalState.loginRequired?`<p class="account-login-required">🔒 请先登录账号，再进入游戏 / 小课堂 / 环保知识探索馆。</p>`:''}<section class="account-login"><div class="account-login-heading"><h3>账号登录</h3>${account?`<span class="account-status">已登录</span>`:''}</div>${account?`<p class="account-session">当前账号：<strong>${escape(activeAccount)}</strong></p><p class="account-session">正式答题：${account.formalQuizUsed?'已参加（不可重做）':'尚未参加'} · 答题积分：${Number(account.quizPoints)||0}</p><button type="button" class="secondary-button" data-action="account-logout">退出登录</button>`:`<form id="account-auth-form" class="account-auth-form"><div class="form-field"><label for="account-username">账号（3–20位字母、数字或下划线）</label><input id="account-username" name="username" minlength="3" maxlength="20" pattern="[A-Za-z0-9_]{3,20}" autocomplete="username" required></div><div class="form-field"><label for="account-password">密码（至少6位）</label><input id="account-password" name="password" type="password" minlength="6" autocomplete="current-password" required></div><p id="account-auth-error" class="form-error" role="alert"></p><div class="modal-actions"><button class="primary-button" type="submit" value="login" name="account-mode">登录</button><button class="secondary-button" type="submit" value="register" name="account-mode">注册账号</button></div></form>`}</section><form id="profile-form" class="profile-form"><div class="avatar-preview ${profile.color}-swatch" data-frame="${escape(profile.frame)}"><img src="assets/mascot.webp" alt=""></div><div class="form-field"><label for="profile-name">${E('account.name')}</label><input id="profile-name" name="name" type="text" value="${escape(profile.name)}" maxlength="24" required autocomplete="nickname"></div><div class="form-field"><label>${E('account.badge')}</label><div class="color-options">${['green','blue','orange','purple'].map((color,i)=>`<button type="button" class="color-option ${color}-swatch ${profile.color===color?'active':''}" data-action="avatar" data-color="${color}" aria-label="头像颜色${i+1}" aria-pressed="${profile.color===color}"></button>`).join('')}</div></div><div class="account-title"><small>${E('account.titleLabel')}</small><strong>${profile.title?E('reward.'+profile.title+'.name'):E('account.noTitle')}</strong></div><div class="account-wallet">${icon('coin')}<div>${E('account.points')}<strong>${w.balance}</strong></div><button type="button" class="secondary-button" data-action="shop" data-filter="owned">${E('account.rewards')}</button></div><div class="stats-grid"><div class="stat"><strong>${p.done}</strong><span>${E('account.games')}</span></div><div class="stat"><strong>${state.lessons.length}</strong><span>${E('account.lessons')}</span></div><div class="stat"><strong>${state.history.length}</strong><span>${E('account.history')}</span></div></div><div class="modal-actions"><button class="primary-button" type="submit">${icon('check')}${E('account.save')}</button></div></form><section class="account-backup"><h3>学习档案备份</h3><p>导出当前玩家的积分、游戏进度、课程完成情况、奖励与兑换记录。建议更换设备或清理浏览器前先备份。</p><div class="modal-actions"><button type="button" class="secondary-button" data-action="account-export">导出我的档案</button><label class="secondary-button shop-import-label" for="account-import-file">恢复档案</label><input id="account-import-file" type="file" accept="application/json,.json" hidden></div><small>恢复会替换当前玩家档案，导入前会要求确认；不会覆盖其他账号或全局商品库存。</small></section>`;}
  function settingsDialog(){return `${modalHeader('settings.title','settings.subtitle')}<div class="settings-row"><div class="row-label"><div><strong>${E('settings.music')}</strong><p>${E('settings.musicHint')}</p></div><button class="toggle" data-action="setting" data-setting="music" role="switch" aria-checked="${!!state.settings.music}" aria-label="${escape(t('settings.music'))}"></button></div></div><div class="settings-row"><div class="row-label"><div><strong>${E('settings.sfx')}</strong><p>${E('settings.sfxHint')}</p></div><button class="toggle" data-action="setting" data-setting="sfx" role="switch" aria-checked="${!!state.settings.sfx}" aria-label="${escape(t('settings.sfx'))}"></button></div></div><div class="settings-row"><div class="row-label"><strong>${E('settings.volume')}</strong><span id="volume-number">${Math.round(state.settings.volume*100)}%</span></div><label class="sr-only" for="volume">${escape(t('settings.volume'))}</label><input id="volume" type="range" min="0" max="100" value="${Math.round(state.settings.volume*100)}"></div><div class="settings-row"><div class="row-label"><strong>音效音量</strong><span id="sfx-volume-number">${Math.round(state.settings.sfxVolume*100)}%</span></div><label class="sr-only" for="sfx-volume">音效音量</label><input id="sfx-volume" type="range" min="0" max="100" value="${Math.round(state.settings.sfxVolume*100)}"></div><div class="settings-row"><div class="row-label"><div><strong>${E('settings.motion')}</strong><p>${E('settings.motionHint')}</p></div><button class="toggle" data-action="setting" data-setting="reduceMotion" role="switch" aria-checked="${!!state.settings.reduceMotion}" aria-label="${escape(t('settings.motion'))}"></button></div></div><div class="settings-row"><div class="row-label"><div><strong>${E('settings.reset')}</strong><p>${E('settings.resetHint')}</p></div><button class="secondary-button" data-action="reset-dialog" aria-label="${escape(t('settings.reset'))}">${icon('history')}</button></div></div><div class="modal-actions"><button class="secondary-button" data-action="password-change">${icon('lock')}${E('settings.password')}</button></div><p class="hint">${E('settings.local')}</p>`;}
  function rewardArt(item){if(item.image)return `<div class="reward-art uploaded-art"><img src="${escape(item.image)}" alt="${escape(item.name)}"></div>`;return item.type==='frame'?`<div class="reward-art frame-art ${item.color}" data-frame="${item.id}"><img src="assets/mascot.webp" alt=""></div>`:`<div class="reward-art title-art ${item.color}">${icon(item.icon)}</div>`}
  function shopDialog(){const w=K.wallet(state),filter=modalState.filter||'all',items=C.shop.filter(item=>filter!=='owned'||w.redeemedItems.includes(item.id));const grStats=K.gameReviewStats?K.gameReviewStats(state):{pending:0},pendingWrong=grStats.pending||0;const hints=[];if(!exhibitionMode&&pendingWrong>0)hints.push(`<li>错题本还有 <b>${pendingWrong}</b> 题待消灭，消灭答对即可恢复积分 <button class="hint-btn" data-action="game-review">去错题本 →</button></li>`);for(const gid of ['runner','match']){const game=C.games.find(x=>x.id===gid);if(!game)continue;const rec=state.records[gid]||{};const cleared=exhibitionMode?[0,1]:(rec.cleared||[]);[0,1].forEach(n=>{if(!cleared.includes(n)){const goal=gid==='runner'?[20,25][n]:[300,500][n];hints.push(`<li>「${escape(t('game.'+gid+'.title'))}」第${n+1}关还没通关，完成可获得 <b>${Math.floor(goal/10)}</b> 积分 <button class="hint-btn" data-action="game" data-game="${gid}">去挑战 →</button></li>`)}})}C.games.filter(g=>['sorter','ludo'].includes(g.id)&&!state.completed[g.id]).forEach(g=>{hints.push(`<li>「${escape(t('game.'+g.id+'.title'))}」正式局还没挑战，完成可获得积分 <button class="hint-btn" data-action="game" data-game="${g.id}">去挑战 →</button></li>`)});if(!state.history.some(h=>h.type==='quiz'))hints.push(`<li>环保知识小测验还没完成，答对同样赚积分 <button class="hint-btn" data-action="classroom">去测验 →</button></li>`);const hintBlock=hints.length?`<div class="shop-points-hint"><h4>${icon('spark')}积分还能这样赚</h4><ul>${hints.join('')}</ul></div>`:'';return `${modalHeader('shop.title','shop.subtitle')}${hintBlock}<div class="shop-wallet"><div class="coin-medallion">${icon('coin')}</div><div><span>${E('shop.available')}</span><strong>${w.balance}<small>${E('points.short')}</small></strong></div><div class="wallet-totals"><span>${E('shop.earned')} <b>${w.earned}</b></span><span>${E('shop.spent')} <b>${w.spent}</b></span></div></div><p class="points-rule">${icon('spark')}积分可兑换线下实物奖励；请凭兑换记录向老师领取。</p><div class="history-filters">${['all','owned'].map(f=>`<button class="filter-button ${filter===f?'active':''}" data-action="shop-filter" data-filter="${f}">${E('shop.'+f)}</button>`).join('')}${w.preview?`<span class="shop-preview">${E('shop.preview')}</span>`:''}<button class="secondary-button shop-manage" data-action="shop-manage">🔐 老师管理商品</button></div>${items.length?`<div class="reward-grid">${items.map(item=>{const owned=item.type!=='physical'&&w.owned.includes(item.id),hasRedeemed=w.redeemedItems.includes(item.id),active=item.type!=='physical'&&state.profile[item.type]===item.id,short=!owned&&w.balance<item.cost,stock=Number.isFinite(Number(item.stock))?Math.max(0,Number(item.stock)):null,unavailable=stock===0;return `<article class="reward-card ${escape(item.color||'mint')} ${item.type==='physical'?'physical-reward':''}" data-reward="${escape(item.id)}"><span class="reward-type">${escape(item.category|| (item.type==='physical'?'线下实物':item.type==='title'?'环保称号':'头像装饰'))}</span>${hasRedeemed?`<span class="reward-owned">${icon('check')}${item.type==='physical'?'已有兑换记录':'已兑换'}</span>`:''}${rewardArt(item)}<h3>${escape(item.name)}</h3><p>${escape(item.description||'环保活动奖励')}</p>${stock!==null?`<small class="stock-label">剩余 ${stock} 件</small>`:''}<div class="reward-bottom"><span class="reward-price">${icon('coin')}${escape(String(item.cost))} 积分</span><button class="${owned?'secondary':'primary'}-button" data-action="${owned&&item.type!=='physical'?'equip-reward':'redeem-dialog'}" data-reward="${escape(item.id)}" ${active||short||unavailable||(owned&&item.type==='physical')?'disabled':''}>${active?'正在使用':owned?'已兑换':unavailable?'暂时缺货':short?'积分不足':item.type==='physical'?'兑换实物':'兑换奖励'}</button></div></article>`}).join('')}</div>`:`<div class="empty-state">${icon('shop')}<p>${E('shop.empty')}</p><button class="primary-button" data-action="show-games">${E('shop.returnGames')}${icon('arrow')}</button></div>`}<p class="hint">商品、照片和库存保存在当前浏览器；更换设备前请在老师管理中导出备份。</p>`}
  function redemptionAdminSection(){
    const orders=[];const accounts=readAccounts();
    for(const username of Object.keys(accounts)){try{const raw=JSON.parse(storage.getItem(accountStateKey(username))||'null');if(!raw)continue;const normalized=K.normalize(raw);for(const [rid,r] of Object.entries(normalized.wallet.redemptions||{}))if(r.type==='physical')orders.push({username,rid,...r})}catch{}}
    try{const raw=JSON.parse(storage.getItem(K.STATE_KEY)||'null');if(raw){const normalized=K.normalize(raw);for(const [rid,r] of Object.entries(normalized.wallet.redemptions||{}))if(r.type==='physical')orders.push({username:'未登录玩家',rid,...r,anonymous:true})}}catch{}
    orders.sort((a,b)=>(b.time||0)-(a.time||0));
    return `<section class="shop-orders"><h3>班级学习档案</h3><p>汇总本浏览器已注册账号的学习进度与积分；导出文件仅包含账号名、完成数和兑换统计，不含密码哈希。</p><div class="shop-backup-actions"><button type="button" class="secondary-button" data-action="class-report-export">导出班级 CSV 报表</button></div><div class="class-roster">${Object.keys(accounts).length?Object.keys(accounts).map(username=>{let st;try{st=K.normalize(JSON.parse(storage.getItem(accountStateKey(username))||'null'))}catch{st=K.normalize(null)}const prog=K.progress(st),wallet=K.wallet(st);return `<div class="class-roster-row"><strong>${escape(username)}</strong><span>游戏 ${prog.done}/4</span><span>课程 ${st.lessons.length}/3</span><span>${wallet.balance} 积分</span><span>兑换 ${wallet.redemptions.length} 笔</span></div>`}).join(''):'<p class="empty-state">尚无注册学生账号。</p>'}</div></section><section class="shop-orders"><h3>实物兑换与发放记录</h3><p>每笔兑换独立记录；学生可以重复兑换同一商品，但每次都会扣积分并占用一件库存。</p>${orders.length?`<div class="shop-orders-list">${orders.slice(0,100).map(o=>`<article class="shop-order"><div><strong>${escape(o.itemName||o.itemId)}</strong><small>学生：${escape(o.username)} · ${escape(timeLabel(o.time))} · ${Number(o.cost)||0} 积分</small></div><span class="shop-order-status ${o.status==='fulfilled'?'done':''}">${o.status==='fulfilled'?'已发放':'待发放'}</span>${o.status!=='fulfilled'?`<button type="button" class="secondary-button" data-action="shop-order-fulfill" data-account="${escape(o.anonymous?'':o.username)}" data-redemption="${escape(o.rid)}">确认已发放</button>`:''}</article>`).join('')}</div>`:'<p class="empty-state">暂时没有实物兑换记录。</p>'}</section>`;
  }
  function shopAdminDialog(){const item=C.shop.find(x=>x.id===modalState.editItem)||{id:'',type:'physical',cost:100,name:'',description:'',stock:10,category:'其他实物',color:'mint',image:''};if(!item.category)item.category=item.type==='title'?'电子称号':item.type==='frame'?'头像装饰':'其他实物';return `${modalHeader('shop.title',null)}<div class="shop-admin-intro">老师编辑模式：修改名称、说明、积分、库存与照片；支持 CSV 批量导入与模板下载。商品图片会压缩后保存在本机。<div class="shop-backup-actions"><button class="secondary-button" type="button" data-action="shop-export">导出商品备份</button><label class="secondary-button shop-import-label" for="shop-import-file">导入商品备份</label><input id="shop-import-file" type="file" accept="application/json,.json" hidden><button class="secondary-button" type="button" data-action="shop-template">下载商品模板 CSV</button><label class="secondary-button shop-import-label" for="shop-csv-file">CSV 导入商品</label><input id="shop-csv-file" type="file" accept=".csv,text/csv" hidden></div></div>${redemptionAdminSection()}<label class="form-field"><span>选择商品</span><select id="shop-edit-select"><option value="">＋ 新增线下奖励</option>${C.shop.map(x=>`<option value="${escape(x.id)}" ${x.id===item.id?'selected':''}>${escape(x.name)}</option>`).join('')}</select></label><form id="shop-item-form" class="shop-item-form"><input type="hidden" id="shop-item-id" value="${escape(item.id)}"><div class="form-field"><label for="shop-item-name">商品名称</label><input id="shop-item-name" maxlength="80" required value="${escape(item.name)}" placeholder="例如：绿色小盆栽"></div><div class="form-field"><label for="shop-item-desc">商品说明</label><textarea id="shop-item-desc" maxlength="500" rows="3">${escape(item.description||'')}</textarea></div><div class="shop-admin-grid"><div class="form-field"><label for="shop-item-cost">兑换积分</label><input id="shop-item-cost" type="number" min="0" max="100000" value="${Number(item.cost)||0}" required></div><div class="form-field"><label for="shop-item-stock">库存数量</label><input id="shop-item-stock" type="number" min="0" max="100000" value="${Number.isFinite(Number(item.stock))?Number(item.stock):20}" required></div></div><div class="shop-admin-grid"><div class="form-field"><label for="shop-item-category">奖励类型</label><select id="shop-item-category">${['徽章','贴纸','盆栽','环保袋','其他实物','电子称号','头像装饰'].map(c=>`<option ${item.category===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="form-field"><label for="shop-item-color">卡片颜色</label><select id="shop-item-color">${['mint','sky','sun','orange','green','purple'].map(c=>`<option value="${c}" ${item.color===c?'selected':''}>${c}</option>`).join('')}</select></div></div><div class="form-field"><label for="shop-item-photo">替换商品照片</label><input id="shop-item-photo" type="file" accept="image/*"><small>建议使用清晰的商品实拍照；图片会缩小压缩，避免占满浏览器存储。</small><div id="shop-photo-preview" class="shop-photo-preview">${item.image?`<img src="${escape(item.image)}" alt="商品照片预览">`:'尚未设置商品照片'}</div></div><div class="modal-actions"><button class="primary-button" type="submit">保存商品</button><button class="secondary-button" type="button" data-action="shop-admin-back">返回商店</button>${item.id?`<button class="danger-button" type="button" data-action="shop-delete" data-reward="${escape(item.id)}">删除商品</button>`:''}</div><p class="form-error" id="shop-admin-error" role="alert"></p></form>`}
  function certificateDialog(){const name=escape(state.profile.name||'环保小达人'),date=new Date(state.awards.certificateIssued||Date.now()).toLocaleDateString('zh-CN');return `${modalHeader('award.certificateTitle','award.certificateSubtitle')}<div class="certificate-card"><div class="certificate-stars">✦ ✧ ✦</div><div class="certificate-mascot">🌎</div><p>环保学习成就证书</p><h2>${name}</h2><p>已完成 4 种垃圾分类游戏与 3 节环保小课堂</p><div class="certificate-seal">🏅 环保小达人</div><small>颁发日期：${date}</small><p class="certificate-note">你用行动证明：每一次正确分类，都是给地球的一份礼物！</p></div><div class="digital-badge-preview"><span>🏅</span><div><strong>电子环保徽章已佩戴</strong><p>徽章已显示在首页问候区，可随时点击查看证书。</p></div></div><div class="modal-actions"><button class="primary-button" data-action="certificate-print">打印 / 保存为 PDF</button><button class="secondary-button" data-action="close">完成</button></div>`}

  function redeemDialog(){const item=C.shop.find(item=>item.id===modalState.reward),w=K.wallet(state);if(!item)return `${modalHeader('shop.title')}<p>找不到该商品。</p>`;return `${modalHeader('redeem.title')}<div class="redeem-preview">${rewardArt(item)}<h3>${escape(item.name)}</h3><p>${item.type==='physical'?'确认兑换后，请凭本机兑换记录向老师领取实物奖励。':E('redeem.description',{cost:item.cost,balance:Math.max(0,w.balance-item.cost)})}</p></div><div class="modal-actions"><button class="primary-button" data-action="redeem-confirm" data-reward="${item.id}">${icon('check')}${E('redeem.confirm')}</button><button class="secondary-button" data-action="shop">${E('redeem.back')}</button></div>`}
  function redeemReward(id){const item=C.shop.find(x=>x.id===id);if(!item){toast('商品不存在或已被删除。');return {ok:false,reason:'unknown'}}if(item.type==='physical'&&Number.isFinite(Number(item.stock))&&Number(item.stock)<=0){toast('该实物已缺货，请联系老师。');openDialog('shop');return {ok:false,reason:'stock'}}const nextState=JSON.parse(JSON.stringify(state)),nextCatalog=JSON.parse(JSON.stringify(C.shop)),catalogItem=nextCatalog.find(x=>x.id===id);const result=K.redeem(nextState,id,Date.now(),nextCatalog);if(!result.ok){toast(result.reason==='owned'?'toast.owned':result.reason==='stock'?'该实物已缺货，请联系老师。':'toast.insufficient');if(modalState?.type==='redeem')openDialog('shop');return result}if(catalogItem?.type==='physical'&&Number.isFinite(Number(catalogItem.stock)))catalogItem.stock=Math.max(0,Number(catalogItem.stock)-1);if(!saveShopCatalog(nextCatalog)){toast('兑换未完成：库存保存失败，没有扣除积分。');return {ok:false,reason:'storage'}}if(!K.write(stateStorage,nextState)){saveShopCatalog(C.shop);toast('兑换未完成：积分记录保存失败，库存已尝试恢复。');return {ok:false,reason:'storage'}}C.shop.splice(0,C.shop.length,...nextCatalog);state=nextState;renderHall();openDialog('shop',{filter:'owned'});toast('toast.redeemed');FX.celebrate({kind:'lesson',anchor:modal.querySelector(`.reward-card[data-reward="${id}"]`)});document.dispatchEvent(new CustomEvent('hub:wallet',{detail:K.wallet(state)}));return result}
  function equipReward(id){if(!K.equip(state,id))return false;persist();renderHall();if(modalState)renderDialog();toast('toast.equipped');return true}
  const timeLabel=value=>{const d=new Date(Number(value));return isNaN(d)?'':new Intl.DateTimeFormat('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Shanghai'}).format(d)};
  function historyDialog(){
    const filter=modalState.filter||'all';
    const items=state.history.filter(h=>filter==='all'||(filter==='games'&&['view','run'].includes(h.type))||(filter==='lessons'&&['lesson','quiz'].includes(h.type))||(filter==='progress'&&['preview','game','reset'].includes(h.type))||(filter==='wallet'&&['points','redeem','equip','run'].includes(h.type)));
    const rows=items.map(h=>{
      const g=C.games.find(g=>g.id===h.item),l=C.lessons.find(l=>l.id===h.item),reward=C.shop.find(item=>item.id===h.item);
      const label=h.type==='quiz'?t('quiz.title'):g?t('game.'+g.id+'.title'):l?t('lesson.'+l.id+'.title'):reward?t('reward.'+reward.id+'.name'):t('progress.title');
      const keys={view:'history.view',lesson:'history.lessonDone',preview:'history.demo',game:'history.gameDone',reset:'history.reset',points:'history.points',redeem:'history.redeem',equip:'history.equip',run:'history.run',quiz:'history.quiz'};
      return `<li class="history-item"><span class="history-symbol">${icon(['points','redeem'].includes(h.type)?'coin':h.type==='equip'?'shop':h.type==='lesson'?'book':h.type==='view'?'leaf':'star')}</span><div><strong>${escape(label)}</strong><p>${E(keys[h.type]||'history.view',{points:Number(h.amount??h.cost)||0,score:Number(h.score)||0})}</p></div><time>${escape(timeLabel(h.time))}</time></li>`;
    }).join('');
    return `${modalHeader('history.title','history.subtitle')}<div class="history-filters">${['all','games','lessons','progress','wallet'].map(f=>`<button class="filter-button ${filter===f?'active':''}" data-action="history-filter" data-filter="${f}">${E('history.'+f)}</button>`).join('')}</div>${items.length?`<ul class="history-list">${rows}</ul>`:`<div class="empty-state">${icon('leaf')}<p>${E('history.empty')}</p><button class="secondary-button" data-action="classroom">${E('history.emptyAction')}${icon('arrow')}</button></div>`}`;
  }
  function authDialog(){return `<div class="auth-lock">${icon('lock')}</div>${modalHeader('admin.unlockTitle','输入固定管理员密码后即可编辑。密码固定，不提供修改入口。')}<form id="auth-form" class="auth-form"><div class="form-field"><label for="auth-password">管理员密码</label><input id="auth-password" type="password" autocomplete="current-password" autofocus required></div><p class="form-error" id="auth-error" role="alert"></p><div class="modal-actions"><button class="primary-button" type="submit" id="auth-submit">${icon('lock')}解锁编辑</button><button class="secondary-button" type="button" data-action="close">${E('common.cancel')}</button></div><p class="hint">密码固定为管理员指定值；此网页端口令仅用于编辑入口，不等同于服务器端安全权限。</p></form>`;}
  function renderDialog(){if(!modalState)return;const type=modalState.type;modal.dataset.view=type;modal.classList.toggle('small-modal',['account','settings','admin','reset','redeem','shop-admin','exhibition-name'].includes(type));const body=type==='game'?gameDialog():type==='classroom'?`${modalHeader('lesson.title','lesson.subtitle')}${window.EcoMuseum.render({state,view:modalState.museumView,prev:modalState.museumPrevCat||null})}`:type==='quiz-mode'?quizModeDialog():type==='quiz'?quizDialog():type==='leaderboard'?leaderboardDialog():type==='game-review'?gameReviewDialog():type==='exhibition-name'?exhibitionNameDialog():type==='guide'?`${modalHeader('lesson.poster','lesson.sourceNote')}<div class="guide-scroll"><img class="guide-poster" src="assets/shanghai-guide.jpg" alt="2019年上海市生活垃圾分类投放指南原图"><h3 class="guide-heading">原图要点 · 一眼看懂四分类</h3><ul class="guide-keypoints"><li><em>可回收物</em>：废纸、塑料、玻璃、金属、织物，保持清洁、沥干水分后投放。</li><li><em>有害垃圾</em>：电池、灯管、药品、油漆桶等，轻投轻放，防止破损。</li><li><em>湿垃圾</em>：剩饭剩菜、瓜皮果核、花卉绿植，去除包装后沥干投放。</li><li><em>干垃圾</em>：纸巾、陶瓷碎片、烟蒂、灰土等，袋装后投放。</li><li><em>大件垃圾</em>：沙发、床垫、桌子可预约回收，或投放到大件垃圾管理责任人指定的场所。</li><li><em>装修垃圾</em>：碎砖、碎石、废砂浆装袋后投放到指定的装修垃圾堆放场所。</li><li><em>电子废弃物</em>：大型电器联系电子废弃物回收企业；小型电子产品按可回收物要求投放。</li><li><em>投放要求</em>：分类投放、专袋专桶，认清四分类标识；干净的可回收物不要混入湿垃圾。</li></ul></div><div class="modal-actions"><button class="primary-button" data-action="classroom">${E('intro.lesson')}</button></div>`:type==='account'?accountDialog():type==='settings'?settingsDialog():type==='history'?historyDialog():type==='admin'?authDialog():type==='shop'?shopDialog():type==='shop-admin'?shopAdminDialog():type==='certificate'?certificateDialog():type==='redeem'?redeemDialog():`${modalHeader('reset.title','reset.description')}<div class="modal-actions"><button class="danger-button" data-action="reset-confirm">${E('reset.confirm')}</button><button class="secondary-button" data-action="close">${E('common.cancel')}</button></div>`;$('modal-body').innerHTML=resolveImages(`<div class="modal-scroll">${body}</div>`);$('modal-body').insertAdjacentHTML('beforeend',audioDock());if(type==='quiz'){if(modalState.quiz.selected===null)startQuizTimer();else{stopQuizTimer();startQuizAutoAdvance(modalState.quiz)}}else{stopQuizTimer();stopQuizAuto()}}
  let itemsDraft=null,quizDraft=null;
  const catLabel={blue:'可回收物',brown:'湿垃圾',red:'有害垃圾',black:'干垃圾'};
  const catOfLabel=label=>D.categories.find(c=>c.name===label||catLabel[c.id]===label)?.id||null;
  const knownImages=['apple-core','banana-peel','bandage','big-bone','bread','button-battery','cabbage-leaf','cardboard','ceramic-shard','cigarette-butt','corn-cob','disinfectant','egg-shell','expired-nail-polish','expired-pills','glass-bottle','hard-shell','lamp-tube','led-bulb','leftover-noodles','metal-can','metal-hanger','milk-tea-cup','newspaper','old-book','paint-can','plastic-bottle','rechargeable-battery','shirt','shrimp-shell','takeout-box','thermometer','used-tissue','walnut-shell','watermelon-rind'];
  function slugId(name,prefix){const s=String(name||'').trim();if(!s)return prefix+Date.now().toString(36);let hex='';for(const ch of s)hex+=ch.codePointAt(0).toString(36);return prefix+hex.slice(0,40)}
  function parseCsv(text){text=String(text||'').replace(/^\uFEFF/,'').replace(/\r\n?/g,'\n');const rows=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(quoted){if(ch==='"'){if(text[i+1]==='"'){field+='"';i++}else quoted=false}else field+=ch}else if(ch==='"')quoted=true;else if(ch===','){row.push(field);field=''}else if(ch==='\n'){row.push(field);field='';rows.push(row);row=[]}else field+=ch}if(field!==''||row.length){row.push(field);rows.push(row)}return rows.filter(r=>r.some(v=>String(v).trim()!==''))}
  function toCsv(rows){return '\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n')}
  function downloadText(name,text,type='text/csv;charset=utf-8'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
  function saveItems(items){if(!saveAdminJson(ITEMS_KEY,items))return false;D.items.splice(0,D.items.length,...items);D.byId=Object.fromEntries(D.items.map(i=>[i.id,i]));D.forCategory=id=>D.items.filter(i=>i.category===id);renderHall();return true}
  function saveQuizBank(quiz){if(!saveAdminJson(QUIZ_KEY,quiz))return false;window.EcoQuizBank.splice(0,window.EcoQuizBank.length,...quiz);return true}
  function itemsTemplateCsv(){const sample=['newspaper','plastic-bottle','banana-peel','rechargeable-battery','big-bone','corn-cob'].map(id=>D.byId[id]).filter(Boolean);const rows=[['ID','名称','类别','图片','分类原因','描述']];for(const i of sample)rows.push([i.id,i.name,catLabel[i.category],i.image,i.why,i.desc]);if(rows.length===1)rows.push(['newspaper','报纸','可回收物','assets/trash/newspaper.png','干净的报纸属于可回收物。','a folded old newspaper with abstract printed lines']);return toCsv(rows)}
  function quizTemplateCsv(){const bank=window.EcoQuizBank||[];const rows=[['题目','A','B','C','D','答案','解析','主题']];for(const q of (bank.slice(0,4).length?bank.slice(0,4):[{question:'旧报纸应该投进哪个垃圾桶？',options:['可回收物','湿垃圾','有害垃圾','干垃圾'],answer:0,why:'干净的旧报纸属于可回收物。',topic:'上海生活垃圾分类'}]) )rows.push([q.question,q.options[0]||'',q.options[1]||'',q.options[2]||'',q.options[3]||'',String.fromCharCode(65+(Number(q.answer)||0)),q.why||'',q.topic||'上海生活垃圾分类']);return toCsv(rows)}
  function shopTemplateCsv(){const rows=[['商品名称','积分','库存','图片','介绍','类型','分类']];for(const i of C.shop.slice(0,6))rows.push([i.name,i.cost,Number.isFinite(Number(i.stock))?i.stock:20,i.image||'',i.description||'',i.type==='title'?'电子称号':i.type==='frame'?'头像装饰':'线下实物',i.category||'其他实物']);if(rows.length===1)rows.push(['环保小徽章',80,30,'','线下领取一枚环保主题徽章。','线下实物','徽章']);return toCsv(rows)}
  function itemsCrudForm(d){d=d||{};const imageOptions=`<option value="">（留空，导入时自动使用默认素材）</option>${knownImages.map(f=>`<option value="assets/trash/${f}.png" ${d.image==='assets/trash/'+f+'.png'?'selected':''}>${f}.png</option>`).join('')}`;return `<form id="items-crud-form" class="editor-crud-form"><input type="hidden" id="crud-item-id" value="${escape(d.id||'')}"><div class="shop-admin-grid"><div class="form-field"><label>物品名称</label><input id="crud-item-name" maxlength="40" required value="${escape(d.name||'')}"></div><div class="form-field"><label>类别</label><select id="crud-item-category">${D.categories.map(c=>`<option value="${c.id}" ${d.category===c.id?'selected':''}>${catLabel[c.id]}</option>`).join('')}</select></div></div><div class="form-field"><label>图片素材</label><select id="crud-item-image">${imageOptions}</select><small>选择已有素材路径，或按模板格式填写 assets/trash/xxx.png。</small></div><div class="form-field"><label>分类原因（答题 / 卡片故事用）</label><textarea id="crud-item-why" maxlength="500" required>${escape(d.why||'')}</textarea></div><div class="form-field"><label>描述（英文素材描述）</label><textarea id="crud-item-desc" maxlength="1000">${escape(d.desc||'')}</textarea></div><div class="editor-actions"><button class="primary-button" type="submit">保存物品</button><button class="secondary-button" type="button" data-action="crud-cancel">取消</button></div><p class="editor-help" id="items-crud-status" role="status"></p></form>`}
  function quizCrudForm(d){d=d||{};const opts=(d.options&&d.options.length?d.options:['','','','']),sel=String.fromCharCode(65+(Number(d.answer)||0));return `<form id="quiz-crud-form" class="editor-crud-form"><input type="hidden" id="crud-quiz-id" value="${escape(d.id||'')}"><div class="form-field"><label>题干</label><textarea id="crud-quiz-question" maxlength="500" required>${escape(d.question||'')}</textarea></div><div class="shop-admin-grid">${[0,1,2,3].map(i=>`<div class="form-field"><label>选项${String.fromCharCode(65+i)}</label><input id="crud-quiz-opt-${i}" maxlength="200" value="${escape(opts[i]||'')}" required></div>`).join('')}</div><div class="shop-admin-grid"><div class="form-field"><label>正确答案</label><select id="crud-quiz-answer">${['A','B','C','D'].map(v=>`<option ${sel===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="form-field"><label>主题</label><input id="crud-quiz-topic" maxlength="60" value="${escape(d.topic||'上海生活垃圾分类')}"></div></div><div class="form-field"><label>解析（为什么）</label><textarea id="crud-quiz-why" maxlength="1000" required>${escape(d.why||'')}</textarea></div><div class="editor-actions"><button class="primary-button" type="submit">保存题目</button><button class="secondary-button" type="button" data-action="crud-cancel">取消</button></div><p class="editor-help" id="quiz-crud-status" role="status"></p></form>`}
